import java.nio.file.*;import java.util.*;import java.util.concurrent.*;public class ResultProcessor{static class Result{final Path file;final boolean ok;final String detail;Result(Path f,boolean o,String d){file=f;ok=o;detail=d;}}static Result process(Path p){try{String s=Files.readString(p).trim();if(s.isEmpty())throw new IllegalArgumentException("Empty score file");int score=Integer.parseInt(s);if(score<0||score>100)throw new IllegalArgumentException("Score outside 0..100");return new Result(p,true,"score="+score);}catch(Exception e){return new Result(p,false,e.getClass().getSimpleName()+": "+e.getMessage());}}public static void main(String[]x)throws Exception{Path d=Files.createTempDirectory("results"),a=d.resolve("a.txt"),b=d.resolve("b.txt"),missing=d.resolve("missing.txt");Files.writeString(a,"86");Files.writeString(b,"bad");List<Path>files=Arrays.asList(a,b,missing);ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<Result>>futures=new ArrayList<>();for(Path p:files)futures.add(pool.submit(()->process(p)));int ok=0,failed=0;for(Future<Result>f:futures){Result r=f.get();System.out.println(r.file.getFileName()+": "+r.detail);if(r.ok)ok++;else failed++;}System.out.println("Successes: "+ok+", failures: "+failed);}finally{pool.shutdown();pool.awaitTermination(1,TimeUnit.MINUTES);}Files.deleteIfExists(a);Files.deleteIfExists(b);Files.deleteIfExists(d);}}